from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
import requests
import os
import json

app = Flask(__name__)
CORS(app)

MODAL_API_URL = "https://api.us-west-2.modal.direct/v1/chat/completions"
MODAL_API_KEY = os.environ.get("MODAL_API_KEY", "")

@app.route('/')
def index():
    return send_from_directory('.', 'index.html')

@app.route('/api/chat', methods=['POST'])
def chat():
    data = request.get_json()
    user_message = data.get('message', '')
    conversation_history = data.get('history', [])

    messages = []
    for msg in conversation_history:
        messages.append({"role": msg["role"], "content": msg["content"]})
    messages.append({"role": "user", "content": user_message})

    payload = {
        "model": "zai-org/GLM-5-FP8",
        "messages": messages,
        "max_tokens": 4000,
        "temperature": 0.7,
        "stream": False
    }

    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {MODAL_API_KEY}"
    }

    try:
        response = requests.post(MODAL_API_URL, json=payload, headers=headers, timeout=120)
        response.raise_for_status()
        result = response.json()
        assistant_message = result["choices"][0]["message"]["content"]
        return jsonify({"response": assistant_message, "success": True})
    except requests.exceptions.RequestException as e:
        return jsonify({"response": f"Error: {str(e)}", "success": False}), 500
    except (KeyError, IndexError) as e:
        return jsonify({"response": "Invalid response format", "success": False}), 500

@app.route('/api/stream', methods=['POST'])
def stream_chat():
    data = request.get_json()
    user_message = data.get('message', '')
    conversation_history = data.get('history', [])

    messages = []
    for msg in conversation_history:
        messages.append({"role": msg["role"], "content": msg["content"]})
    messages.append({"role": "user", "content": user_message})

    payload = {
        "model": "zai-org/GLM-5-FP8",
        "messages": messages,
        "max_tokens": 4000,
        "temperature": 0.7,
        "stream": True
    }

    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {MODAL_API_KEY}"
    }

    def generate():
        try:
            response = requests.post(MODAL_API_URL, json=payload, headers=headers, stream=True, timeout=120)
            response.raise_for_status()
            for line in response.iter_lines():
                if line:
                    decoded_line = line.decode('utf-8')
                    if decoded_line.startswith('data: '):
                        data_str = decoded_line[6:]
                        if data_str.strip() == '[DONE]':
                            break
                        try:
                            chunk_data = json.loads(data_str)
                            if 'choices' in chunk_data and len(chunk_data['choices']) > 0:
                                delta = chunk_data['choices'][0].get('delta', {})
                                content = delta.get('content', '')
                                if content:
                                    yield f"data: {json.dumps({'content': content})}\n\n"
                        except json.JSONDecodeError:
                            continue
        except Exception as e:
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    return app.response_class(generate(), mimetype='text/event-stream')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)


