from flask import Flask, request, jsonify, send_from_directory, Response
from flask_cors import CORS
import requests
import os
import json

app = Flask(__name__)
CORS(app)

MODAL_API_URL = "https://api.us-west-2.modal.direct/v1/chat/completions"
MODAL_API_KEY = os.environ.get("MODAL_API_KEY", "")

MAX_TOKENS = 128000

@app.route('/')
def index():
    return send_from_directory('.', 'index.html')

@app.route('/api/stream', methods=['POST'])
def stream_chat():
    data = request.get_json()
    user_message = data.get('message', '')
    conversation_history = data.get('history', [])

    messages = []
    for msg in conversation_history:
        entry = {"role": msg["role"], "content": msg["content"]}
        if msg.get("reasoning_content"):
            entry["reasoning_content"] = msg["reasoning_content"]
        messages.append(entry)
    messages.append({"role": "user", "content": user_message})

    payload = {
        "model": "zai-org/GLM-5-FP8",
        "messages": messages,
        "max_tokens": MAX_TOKENS,
        "temperature": 1.0,
        "top_p": 0.95,
        "stream": True,
        "thinking": {
            "type": "enabled",
            "clear_thinking": False
        }
    }

    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {MODAL_API_KEY}"
    }

    def generate():
        try:
            response = requests.post(
                MODAL_API_URL,
                json=payload,
                headers=headers,
                stream=True,
                timeout=600
            )
            response.raise_for_status()

            for line in response.iter_lines(decode_unicode=True):
                if line:
                    if line.startswith('data: '):
                        data_str = line[6:]
                        if data_str.strip() == '[DONE]':
                            yield f"data: {json.dumps({'done': True})}\n\n"
                            break
                        try:
                            chunk_data = json.loads(data_str)
                            if 'choices' in chunk_data and chunk_data['choices']:
                                delta = chunk_data['choices'][0].get('delta', {})
                                reasoning = delta.get('reasoning_content', '')
                                content = delta.get('content', '')
                                finish_reason = chunk_data['choices'][0].get('finish_reason')

                                out = {}
                                if reasoning:
                                    out['reasoning'] = reasoning
                                if content:
                                    out['content'] = content
                                if finish_reason:
                                    out['finish_reason'] = finish_reason
                                if out:
                                    yield f"data: {json.dumps(out)}\n\n"
                        except json.JSONDecodeError:
                            continue
        except requests.exceptions.Timeout:
            yield f"data: {json.dumps({'error': 'Timeout: a válasz túl hosszú volt (600s).'})}\n\n"
        except requests.exceptions.RequestException as e:
            yield f"data: {json.dumps({'error': str(e)})}\n\n"
        except Exception as e:
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    return Response(
        generate(),
        mimetype='text/event-stream',
        headers={
            'Cache-Control': 'no-cache',
            'Connection': 'keep-alive',
            'X-Accel-Buffering': 'no',
            'Access-Control-Allow-Origin': '*'
        }
    )

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 5000))
    app.run(host='0.0.0.0', port=port, debug=False, threaded=True)


