                                    reasoningDone = true;
                                    reasoningHeader.textContent = 'Gondolkodás befejezve';
                                    reasoningHeader.className = 'reasoning-header done';
                                }
                                fullContent += chunk.content;
                                contentBlock.style.display = 'block';
                                contentBlock.textContent = fullContent;
                                scrollToBottom();
                                totalTokensEstimate += estimateTokens(chunk.content);
                                updateTokenBar();
                            }

                        } catch (parseErr) {
                            continue;
                        }
                    }
                }
            }

            if (fullContent) {
                conversationHistory.push({
                    role: 'assistant',
                    content: fullContent,
                    reasoning_content: fullReasoning || null
                });
            }

            if (fullReasoning && !fullContent) {
                reasoningHeader.textContent = 'Gondolkodás befejezve (nincs tartalom)';
                reasoningHeader.className = 'reasoning-header done';
            }

        } catch (err) {
            const wrapper = document.getElementById('activeAssistant');
            if (wrapper) {
                contentBlock.style.display = 'block';
                contentBlock.textContent = 'Hiba: ' + err.message;
                contentBlock.style.borderColor = '#ef4444';
                contentBlock.style.color = '#ef4444';
            }
        } finally {
            const activeEl = document.getElementById('activeAssistant');
            if (activeEl) activeEl.removeAttribute('id');
            const activeR = document.getElementById('activeReasoning');
            if (activeR) activeR.removeAttribute('id');
            const activeRT = document.getElementById('activeReasoningText');
            if (activeRT) activeRT.removeAttribute('id');
            const activeC = document.getElementById('activeContent');
            if (activeC) activeC.removeAttribute('id');
            const activeRH = document.getElementById('reasoningHeader');
            if (activeRH) activeRH.removeAttribute('id');

            isProcessing = false;
            sendBtn.disabled = false;
            sendBtn.textContent = 'Küldés';
            input.focus();
        }
    }

    function clearChat() {
        if (isProcessing) return;
        conversationHistory = [];
        totalTokensEstimate = 0;
        updateTokenBar();
        const container = document.getElementById('messagesContainer');
        container.innerHTML = '';
        const wrapper = document.createElement('div');
        wrapper.className = 'message assistant';
        const content = document.createElement('div');
        content.className = 'message-content';
        content.textContent = 'Chat törölve. Új beszélgetés kezdődik.';
        wrapper.appendChild(content);
        container.appendChild(wrapper);
    }

    document.getElementById('messageInput').focus();
    updateTokenBar();
</script>
</body>
</html>
